template.content:
{% if subworkflowContext.MATERIAL_INDEX %}
{%- set input = input.perMaterial[subworkflowContext.MATERIAL_INDEX] -%}
{% endif -%}
&CONTROL
    calculation = 'scf'
    title = ''
    verbosity = 'low'
    restart_mode = '{{ input.RESTART_MODE }}'
    wf_collect = .true.
    tstress = .true.
    tprnfor = .true.
    outdir = {% raw %}'{{ JOB_WORK_DIR }}/outdir'{% endraw %}
    wfcdir = {% raw %}'{{ JOB_WORK_DIR }}/outdir'{% endraw %}
    prefix = '__prefix__'
    pseudo_dir = {% raw %}'{{ JOB_WORK_DIR }}/pseudo'{% endraw %}
/
&SYSTEM
    ibrav = {{ input.IBRAV }}
    nat = {{ input.NAT }}
    ntyp = {{ input.NTYP }}
    ecutwfc = {{ cutoffs.wavefunction }}
    ecutrho = {{ cutoffs.density }}
    occupations = 'smearing'
    degauss = 0.005
/
&ELECTRONS
    diagonalization = 'david'
    diago_david_ndim = 4
    diago_full_acc = .true.
    mixing_beta = 0.3
    startingwfc = 'atomic+random'
/
&IONS
/
&CELL
/
ATOMIC_SPECIES
{% for specie in input.ATOMIC_SPECIES -%}
{{ specie.X }} {{ specie.Mass_X|sprintf("%f") }} {{ specie.PseudoPot_X }}
{% endfor %}
ATOMIC_POSITIONS crystal
{%- set print_constraints = false %}
{%- for position in input.ATOMIC_POSITIONS %}
    {%- if position["if_pos(1)"] != 1 or position["if_pos(2)"] != 1 or position["if_pos(3)"] != 1 %}
        {%- set print_constraints = true %}
    {%- endif %}
{%- endfor %}
{% for position in input.ATOMIC_POSITIONS -%}
{{ position.X|sprintf("%-3s") }} {{ position.x|sprintf("%14.9f") }} {{ position.y|sprintf("%14.9f") }} {{ position.z|sprintf("%14.9f") }}{% if print_constraints %} {{ position["if_pos(1)"] }} {{ position["if_pos(2)"] }} {{ position["if_pos(3)"] }}{% endif %}
{% endfor %}
CELL_PARAMETERS angstrom
{{ input.CELL_PARAMETERS.v1[0]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v1[1]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v1[2]|sprintf("%14.9f") }}
{{ input.CELL_PARAMETERS.v2[0]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v2[1]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v2[2]|sprintf("%14.9f") }}
{{ input.CELL_PARAMETERS.v3[0]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v3[1]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v3[2]|sprintf("%14.9f") }}
K_POINTS automatic
{% for d in kgrid.dimensions %}{{d}} {% endfor %}{% for s in kgrid.shifts %}{{s}} {% endfor %}

&CONTROL
    calculation = 'bands'
    title = ''
    verbosity = 'high'
    restart_mode = '{{ input.RESTART_MODE }}'
    wf_collect = .true.
    outdir = {% raw %}'{{ JOB_WORK_DIR }}/outdir'{% endraw %}
    wfcdir = {% raw %}'{{ JOB_WORK_DIR }}/outdir'{% endraw %}
    prefix = '__prefix__'
    pseudo_dir = {% raw %}'{{ JOB_WORK_DIR }}/pseudo'{% endraw %}
/
&SYSTEM
    ibrav = {{ input.IBRAV }}
    nat = {{ input.NAT }}
    ntyp = {{ input.NTYP }}
    ecutwfc = {{ cutoffs.wavefunction }}
    ecutrho = {{ cutoffs.density }}
{#- Bands in WFN (occupied + unoccupied): must be >= number_bands in epsilon.inp #}
    nbnd = 35
/
&ELECTRONS
    conv_thr = 1.0d-10
    diagonalization = 'david'
    diago_david_ndim = 4
    diago_full_acc = .true.
/
&IONS
/
&CELL
/
ATOMIC_SPECIES
{% for specie in input.ATOMIC_SPECIES -%}
{{ specie.X }} {{ specie.Mass_X|sprintf("%f") }} {{ specie.PseudoPot_X }}
{% endfor %}
ATOMIC_POSITIONS crystal
{%- set print_constraints = false %}
{%- for position in input.ATOMIC_POSITIONS %}
    {%- if position["if_pos(1)"] != 1 or position["if_pos(2)"] != 1 or position["if_pos(3)"] != 1 %}
        {%- set print_constraints = true %}
    {%- endif %}
{%- endfor %}
{% for position in input.ATOMIC_POSITIONS -%}
{{ position.X|sprintf("%-3s") }} {{ position.x|sprintf("%14.9f") }} {{ position.y|sprintf("%14.9f") }} {{ position.z|sprintf("%14.9f") }}{% if print_constraints %} {{ position["if_pos(1)"] }} {{ position["if_pos(2)"] }} {{ position["if_pos(3)"] }}{% endif %}
{% endfor %}
CELL_PARAMETERS angstrom
{{ input.CELL_PARAMETERS.v1[0]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v1[1]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v1[2]|sprintf("%14.9f") }}
{{ input.CELL_PARAMETERS.v2[0]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v2[1]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v2[2]|sprintf("%14.9f") }}
{{ input.CELL_PARAMETERS.v3[0]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v3[1]|sprintf("%14.9f") }} {{ input.CELL_PARAMETERS.v3[2]|sprintf("%14.9f") }}
{#- Full, unshifted (Gamma-centered) k-grid without symmetry reduction: BerkeleyGW unfolds the
    WFN k-points with the crystal symmetries, so the full grid is always a valid (if not the
    cheapest) choice. kgrid.shifts are intentionally ignored: Epsilon expects an unshifted WFN. #}
{%- set n1 = kgrid.dimensions[0] %}
{%- set n2 = kgrid.dimensions[1] %}
{%- set n3 = kgrid.dimensions[2] %}
K_POINTS crystal
{{ n1 * n2 * n3 }}
{% for i in range(n1) -%}
{% for j in range(n2) -%}
{% for k in range(n3) -%}
{{ (i / n1)|sprintf("%14.9f") }} {{ (j / n2)|sprintf("%14.9f") }} {{ (k / n3)|sprintf("%14.9f") }} 1.0
{% endfor -%}
{% endfor -%}
{% endfor -%}
